gmS(){return"\u0391\u03c0\u03cc"},
goJ(){return"\u0388\u03c9\u03c2"},
gmH(){return"\u0395\u03be\u03b1\u03b3\u03c9\u03b3\u03ae"},
gmG(){return"\u0395\u03be\u03b1\u03b3\u03c9\u03b3\u03ae \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03c9\u03bd"},
